    "This 3DS game can't start here." to Tr(ja = "この 3DSソフトは ここでは はじめられません", fr = "Ce jeu 3DS ne peut pas démarrer ici.", de = "Dieses 3DS-Spiel kann hier nicht starten.", it = "Questo gioco 3DS non può partire qui.", es = "Este juego de 3DS no puede iniciarse aquí.", br = "Este jogo de 3DS não pode começar aqui.", pt = "Este jogo de 3DS não pode começar aqui.", ko = "이 3DS 게임은 여기서 시작할 수 없어요."),
    "The 3DS game stopped." to Tr(ja = "3DSソフトが とまりました", fr = "Le jeu 3DS s'est arrêté.", de = "Das 3DS-Spiel wurde beendet.", it = "Il gioco 3DS si è fermato.", es = "El juego de 3DS se ha detenido.", br = "O jogo de 3DS parou.", pt = "O jogo de 3DS parou.", ko = "3DS 게임이 멈췄어요."),
