    "A Pokémon holding mail can't go in the PC" to Tr(ja = "メールを もった ポケモンは パソコンに いれられません", fr = "Un Pokémon qui tient une lettre ne va pas dans le PC", de = "Ein Pokémon mit Brief kann nicht in den PC", it = "Un Pokémon con una lettera non può andare nel PC", es = "Un Pokémon con una carta no puede ir al PC", br = "Um Pokémon com carta não pode ir para o PC", pt = "Um Pokémon com carta não pode ir para o PC", ko = "편지를 지닌 포켓몬은 PC에 맡길 수 없어요"),
    "That's your last Pokémon able to battle" to Tr(ja = "たたかえる ポケモンが いなく なります", fr = "C'est votre dernier Pokémon en état de combattre", de = "Das ist dein letztes kampffähiges Pokémon", it = "È il tuo ultimo Pokémon in grado di lottare", es = "Es tu último Pokémon que puede combatir", br = "É o seu último Pokémon que pode batalhar", pt = "É o seu último Pokémon que pode combater", ko = "싸울 수 있는 마지막 포켓몬이에요"),
    "No Pokémon like that can exist" to Tr(ja = "そんな ポケモンは いません", fr = "Un tel Pokémon ne peut pas exister", de = "So ein Pokémon kann es nicht geben", it = "Un Pokémon così non può esistere", es = "No puede existir un Pokémon así", br = "Não pode existir um Pokémon assim", pt = "Não pode existir um Pokémon assim", ko = "그런 포켓몬은 있을 수 없어요"),
    "An egg can't be released" to Tr(ja = "タマゴは にがせません", fr = "On ne peut pas relâcher un œuf", de = "Ein Ei kann nicht freigelassen werden", it = "Un uovo non si può liberare", es = "Un huevo no se puede liberar", br = "Um ovo não pode ser solto", pt = "Um ovo não pode ser libertado", ko = "알은 놓아줄 수 없어요"),
    "This save has that already" to Tr(ja = "この セーブには もう あります", fr = "Cette sauvegarde l'a déjà", de = "Dieser Spielstand hat das schon", it = "Questo salvataggio lo ha già", es = "Esta partida ya lo tiene", br = "Este save já tem isso", pt = "Esta gravação já tem isso", ko = "이 세이브에는 이미 있어요"),
    "The key items pocket is full" to Tr(ja = "だいじな もの ポケットが いっぱいです", fr = "La poche Objets rares est pleine", de = "Die Basis-Items-Tasche ist voll", it = "La tasca Strumenti base è piena", es = "El bolsillo de objetos clave está lleno", br = "O bolso de itens-chave está cheio", pt = "O bolso de itens-chave está cheio", ko = "중요한 물건 포켓이 가득 찼어요"),
    "That's {0}'s last Pokémon that isn't an egg: it stays in the party" to Tr(ja = "{0}の タマゴでない さいごの ポケモンです: てもちに のこります", fr = "C'est le dernier Pokémon de {0} qui n'est pas un œuf : il reste dans l'équipe", de = "Das ist das letzte Pokémon von {0}, das kein Ei ist: es bleibt im Team", it = "È l'ultimo Pokémon di {0} che non è un uovo: resta nella squadra", es = "Es el último Pokémon de {0} que no es un huevo: se queda en el equipo", br = "É o último Pokémon de {0} que não é ovo: fica na equipe", pt = "É o último Pokémon de {0} que não é ovo: fica na equipe", ko = "{0}의 알이 아닌 마지막 포켓몬이에요: 파티에 남아요"),
    "{0}'s party is full" to Tr(ja = "{0}の てもちは いっぱいです", fr = "L'équipe de {0} est pleine", de = "Das Team von {0} ist voll", it = "La squadra di {0} è piena", es = "El equipo de {0} está lleno", br = "A equipe de {0} está cheia", pt = "A equipe de {0} está cheia", ko = "{0}의 파티가 가득 찼어요"),
    "PAL PARK" to Tr(ja = "パルパーク", fr = "PARC DES AMIS", de = "PARK DER FREUNDE", it = "PARCO AMICI", es = "PARQUE COMPI", br = "PAL PARK", pt = "PAL PARK", ko = "팔파크"),
    "Bring GBA Pokémon to HeartGold, SoulSilver or Platinum" to Tr(ja = "GBAの ポケモンを ハートゴールド、 ソウルシルバー、 プラチナへ", fr = "Amenez des Pokémon GBA dans Or HeartGold, Argent SoulSilver ou Platine", de = "GBA-Pokémon nach HeartGold, SoulSilver oder Platin holen", it = "Porta Pokémon GBA in HeartGold, SoulSilver o Platino", es = "Lleva Pokémon de GBA a HeartGold, SoulSilver o Platino", br = "Leve Pokémon do GBA ao HeartGold, SoulSilver ou Platinum", pt = "Leve Pokémon do GBA ao HeartGold, SoulSilver ou Platinum", ko = "GBA 포켓몬을 하트골드, 소울실버, 플라티나로 데려와요"),
    "PAL PARK needs a GBA game (FireRed, LeafGreen, Emerald, Ruby or Sapphire) and HeartGold, SoulSilver or Platinum, each with a save it can read, saved once in the game." to Tr(ja = "パルパークには よめる セーブの ある GBAの ゲーム (ファイアレッド、 リーフグリーン、 エメラルド、 ルビー、 サファイア) と ハートゴールド、 ソウルシルバー、 プラチナの どれかが いります (ゲームで いちど セーブ)。", fr = "Le Parc des Amis demande un jeu GBA (Rouge Feu, Vert Feuille, Émeraude, Rubis ou Saphir) et Or HeartGold, Argent SoulSilver ou Platine, chacun avec une sauvegarde lisible, sauvegardé une fois en jeu.", de = "Der Park der Freunde braucht ein GBA-Spiel (Feuerrot, Blattgrün, Smaragd, Rubin oder Saphir) und HeartGold, SoulSilver oder Platin, jedes mit lesbarem Spielstand, einmal im Spiel gespeichert.", it = "Il Parco Amici richiede un gioco GBA (Rosso Fuoco, Verde Foglia, Smeraldo, Rubino o Zaffiro) e HeartGold, SoulSilver o Platino, ciascuno con un salvataggio leggibile, salvato una volta nel gioco.", es = "El Parque Compi necesita un juego de GBA (Rojo Fuego, Verde Hoja, Esmeralda, Rubí o Zafiro) y HeartGold, SoulSilver o Platino, cada uno con una partida que pueda leer, guardada una vez en el juego.", br = "O Pal Park precisa de um jogo de GBA (FireRed, LeafGreen, Emerald, Ruby ou Sapphire) e HeartGold, SoulSilver ou Platinum, cada um com um save que ele leia, salvo uma vez no jogo.", pt = "O Pal Park precisa de um jogo de GBA (FireRed, LeafGreen, Emerald, Ruby ou Sapphire) e HeartGold, SoulSilver ou Platinum, cada um com uma gravação que ele leia, gravada uma vez no jogo.", ko = "팔파크에는 읽을 수 있는 세이브가 있는 GBA 게임(파이어레드, 리프그린, 에메랄드, 루비, 사파이어)과 하트골드, 소울실버, 플라티나가 필요해요(게임에서 한 번 리포트)."),
    "Save your changes first, then bring it over" to Tr(ja = "さきに へんこうを セーブしてから つれてきて", fr = "Sauvegardez d'abord vos changements, puis amenez-le", de = "Speichere zuerst deine Änderungen, dann hol es", it = "Salva prima le modifiche, poi portalo qui", es = "Guarda primero los cambios y luego tráelo", br = "Salve as mudanças antes de trazê-lo", pt = "Grave as alterações antes de o trazer", ko = "먼저 변경을 저장한 다음 데려와요"),
    "BRING FROM" to Tr(ja = "つれてくる ゲーム", fr = "AMENER DEPUIS", de = "HOLEN AUS", it = "PORTA DA", es = "TRAER DE", br = "TRAZER DE", pt = "TRAZER DE", ko = "데려올 게임"),
    "BRING TO" to Tr(ja = "つれていく ゲーム", fr = "AMENER DANS", de = "HOLEN NACH", it = "PORTA IN", es = "LLEVAR A", br = "LEVAR PARA", pt = "LEVAR PARA", ko = "데려갈 게임"),
    "Pal Park takes Pokémon from the PC: put it in a box first" to Tr(ja = "パルパークは パソコンの ポケモンだけ: さきに ボックスへ", fr = "Le Parc des Amis prend les Pokémon du PC : mettez-le d'abord dans une boîte", de = "Der Park der Freunde nimmt Pokémon aus dem PC: lege es zuerst in eine Box", it = "Il Parco Amici prende i Pokémon dal PC: mettilo prima in un box", es = "El Parque Compi toma Pokémon del PC: déjalo antes en una caja", br = "O Pal Park pega Pokémon do PC: coloque-o numa caixa antes", pt = "O Pal Park tira Pokémon do PC: põe-no numa caixa antes", ko = "팔파크는 PC의 포켓몬만 받아요: 먼저 박스에 맡겨요"),
    "A Bad Egg can't go to Pal Park" to Tr(ja = "ダメタマゴは パルパークへ いけません", fr = "Un Mauvais Œuf ne peut pas aller au Parc des Amis", de = "Ein schlechtes Ei kann nicht in den Park der Freunde", it = "Un Uovo Guasto non può andare al Parco Amici", es = "Un Huevo Malo no puede ir al Parque Compi", br = "Um Ovo Ruim não pode ir ao Pal Park", pt = "Um Ovo Mau não pode ir ao Pal Park", ko = "불량 알은 팔파크에 갈 수 없어요"),
