    "Pick a Pokémon on one side, then a Pokémon or an empty slot on the other: party or PC" to Tr(ja = "かたほうで ポケモンを えらび、 もう かたほうで ポケモンか あいた ばしょを えらんでください: てもちでも パソコンでも", fr = "Choisissez un Pokémon d'un côté, puis un Pokémon ou une place vide de l'autre : équipe ou PC", de = "Wähle auf einer Seite ein Pokémon, dann auf der anderen ein Pokémon oder einen freien Platz: Team oder PC", it = "Scegli un Pokémon da una parte, poi un Pokémon o un posto vuoto dall'altra: squadra o PC", es = "Elige un Pokémon en un lado y luego un Pokémon o un hueco vacío en el otro: equipo o PC", br = "Escolha um Pokémon de um lado e depois um Pokémon ou espaço vazio do outro: equipe ou PC", pt = "Escolha um Pokémon de um lado e depois um Pokémon ou espaço vazio do outro: equipe ou PC", ko = "한쪽에서 포켓몬을 고르고, 다른 쪽에서 포켓몬이나 빈칸을 고르세요: 파티나 PC"),
