    "{0} doesn't have the item it holds" to Tr(ja = "{0}には もっている どうぐが ありません", fr = "{0} n'a pas l'objet qu'il tient", de = "{0} kennt das getragene Item nicht", it = "{0} non ha lo strumento che tiene", es = "{0} no tiene el objeto que lleva", br = "{0} não tem o item que ele segura", pt = "{0} não tem o item que ele segura", ko = "{0}에는 지닌 도구가 없어요"),
    "This isn't a HeartGold, SoulSilver or Platinum save" to Tr(ja = "これは ハートゴールド・ソウルシルバー・プラチナの セーブでは ありません", fr = "Ce n'est pas une sauvegarde d'Or HeartGold, d'Argent SoulSilver ou de Platine", de = "Das ist kein Spielstand von HeartGold, SoulSilver oder Platin", it = "Questo non è un salvataggio di HeartGold, SoulSilver o Platino", es = "Esta no es una partida de HeartGold, SoulSilver o Platino", br = "Este não é um save de HeartGold, SoulSilver ou Platinum", pt = "Esta não é uma gravação de HeartGold, SoulSilver ou Platinum", ko = "하트골드, 소울실버, 플라티나의 세이브가 아니에요"),
    "This isn't a HeartGold, SoulSilver or Platinum save, or it's damaged" to Tr(ja = "これは ハートゴールド・ソウルシルバー・プラチナの セーブでは ないか、 こわれています", fr = "Ce n'est pas une sauvegarde d'Or HeartGold, d'Argent SoulSilver ou de Platine, ou elle est abîmée", de = "Das ist kein Spielstand von HeartGold, SoulSilver oder Platin, oder er ist beschädigt", it = "Questo non è un salvataggio di HeartGold, SoulSilver o Platino, oppure è danneggiato", es = "Esta no es una partida de HeartGold, SoulSilver o Platino, o está dañada", br = "Este não é um save de HeartGold, SoulSilver ou Platinum, ou está danificado", pt = "Esta não é uma gravação de HeartGold, SoulSilver ou Platinum, ou está danificada", ko = "하트골드, 소울실버, 플라티나의 세이브가 아니거나 손상됐어요"),
    "Mail stays with its letter" to Tr(ja = "メールは てがみと いっしょに のこります", fr = "Une lettre reste avec son message", de = "Ein Brief bleibt bei seiner Nachricht", it = "La lettera resta con il suo messaggio", es = "La carta se queda con su mensaje", br = "A carta fica com a mensagem", pt = "A carta fica com a mensagem", ko = "편지는 내용과 함께 남아요"),
    "The bag has no room for it" to Tr(ja = "バッグに いれる ばしょが ありません", fr = "Le sac n'a plus de place pour l'objet", de = "Im Beutel ist kein Platz dafür", it = "Nella borsa non c'è posto", es = "No hay sitio en la mochila", br = "Não há espaço na mochila", pt = "Não há espaço na mochila", ko = "가방에 넣을 공간이 없어요"),
    "TRADE SAVES needs two games with a save it can read, each saved once in the game: FireRed, LeafGreen, Emerald, Ruby and Sapphire trade with each other, HeartGold, SoulSilver and Platinum with each other." to Tr(ja = "セーブを こうかん するには よめる セーブの ゲームが 2つ いります (ゲームで いちど セーブ): ファイアレッド、 リーフグリーン、 エメラルド、 ルビー、 サファイアどうし、 ハートゴールド、 ソウルシルバー、 プラチナどうしで こうかん できます。", fr = "L'échange de sauvegardes demande deux jeux avec une sauvegarde lisible, sauvegardés une fois en jeu : Rouge Feu, Vert Feuille, Émeraude, Rubis et Saphir échangent entre eux, Or HeartGold, Argent SoulSilver et Platine entre eux.", de = "Spielstände tauschen braucht zwei Spiele mit lesbarem Spielstand, je einmal im Spiel gespeichert: Feuerrot, Blattgrün, Smaragd, Rubin und Saphir tauschen untereinander, HeartGold, SoulSilver und Platin untereinander.", it = "Lo scambio tra salvataggi richiede due giochi con un salvataggio leggibile, salvati una volta nel gioco: Rosso Fuoco, Verde Foglia, Smeraldo, Rubino e Zaffiro scambiano tra loro, HeartGold, SoulSilver e Platino tra loro.", es = "El intercambio de partidas necesita dos juegos con una partida que pueda leer, guardados una vez en el juego: Rojo Fuego, Verde Hoja, Esmeralda, Rubí y Zafiro intercambian entre sí, HeartGold, SoulSilver y Platino entre sí.", br = "A troca entre saves precisa de dois jogos com um save que ela leia, salvos uma vez no jogo: FireRed, LeafGreen, Emerald, Ruby e Sapphire trocam entre si, HeartGold, SoulSilver e Platinum entre si.", pt = "A troca entre gravações precisa de dois jogos com uma gravação que ela leia, gravados uma vez no jogo: FireRed, LeafGreen, Emerald, Ruby e Sapphire trocam entre si, HeartGold, SoulSilver e Platinum entre si.", ko = "세이브 교환에는 읽을 수 있는 세이브가 있는 게임 두 개가 필요해요(게임에서 한 번 리포트): 파이어레드, 리프그린, 에메랄드, 루비, 사파이어끼리, 하트골드, 소울실버, 플라티나끼리 교환할 수 있어요."),
    "This Pichu can't be traded" to Tr(ja = "この ピチューは こうかん できません", fr = "Ce Pichu ne peut pas être échangé", de = "Dieses Pichu kann nicht getauscht werden", it = "Questo Pichu non si può scambiare", es = "Este Pichu no se puede intercambiar", br = "Este Pichu não pode ser trocado", pt = "Este Pichu não pode ser trocado", ko = "이 피츄는 교환할 수 없어요"),
